"""Render manually interpreted themes and the fixed review-source index."""
from pathlib import Path
import datetime as dt
import json

p=Path(__file__).resolve().parent
output=p.parent/'market-reviews.md'
if output.exists():
    raise SystemExit('Preserve manual report edits before regenerating.')
data=json.loads((p/'review-sample-2026-10-21.json').read_text(encoding='utf-8'))['samples']
rows={r['appid']:r for r in json.loads((p/'steam-snapshot-2026-10-21.json').read_text(encoding='utf-8'))['games']}
themes={
2123640:('Atmosphere, tension, setting and ambience are praised.','Substantive complaints cover camera problems, weak weapon feel, easy puzzles, empty/redundant spaces and technical issues. Some entries contain off-topic hostility or little actionable detail.','Atmosphere can attract players while combat and camera still undermine the experience. Do not treat a positive art response as acceptance of the whole game.'),
1257030:('Art, music, nostalgia and atmosphere appeal; one detailed positive review also criticizes transitions, variety and presentation consistency.','Complaints include a frustrating boss/stun combination, controls, thin combat development and a later area becoming tedious.','Test moving, aiming and escaping attacks as one connected sequence. An advertised 4–6-hour game still needs meaningful pacing across its full duration.'),
1750030:('Some players enjoy puzzles, atmosphere, enemy art and a compact story; positive recommendations can still include reservations.','Other readers find the puzzles repetitive, combat limited/buggy and the story or ending unclear.','Clearly communicate whether puzzles or combat lead the experience. Our combat-led concept cannot borrow a puzzle-heavy comparison without accounting for that difference.'),
3463020:('No qualifying positive English-labeled Steam-purchase review was returned.','Two old EA comments question purchase value; one describes missing collision and unclear progression.','These are launch-era opinions, not verification of the current patch. Current-value and onboarding tests matter before charging for EA.'),
3180340:('Boost combat, movement, customization and the Armored Core/roguelite combination appeal; some positive reviews still ask for more content or polish.','Complaints cover boss health/balance, progression tedium, lock-on/camera, simplistic pressure from enemies, unclear upgrades and crashes.','Movement and customization are attractions, but readable targeting and encounter/build variety need their own acceptance tests. More health is not a substitute for richer encounters.'),
2743460:('Customization, equipment fantasy and continuing updates are praised.','Complaints include repetitive objectives, weapon/impact feel, UI explanation, loadout friction and multiplayer failures. One negative entry gives no useful detail.','Preserve mechanical build differences and varied mission decisions. Co-op complaints do not imply that our single-player baseline needs networking.'),
1379120:('Two old EA comments enjoy mech destruction; one also says unlocks and boss kills happened too easily.','The one qualifying negative review compares fluidity and value unfavorably with Risk of Rain 2.','All three sampled comments predate full release. Useful historical expectations, weak evidence about present balance or quality.'),
956680:('Creative mech design is a recurring attraction. Positive recommendations range from liking combat to accepting it mainly as a way to use a custom model.','Criticism covers cosmetic versus functional variety, grind before using preferred parts, targeting/camera, repetitive combat and difficulty spikes. Some entries are not actionable for our scope.','Communicate whether customization changes play, appearance, or both. Do not hide the main building fantasy behind excessive unlocking.'),
3107330:('Short satisfying progression, sound/music, simple interaction and value appeal.','Others dislike the basic repetition, limited change or having to remain active. Some returned entries are jokes/non-English despite the language filter.','Aim at an active incremental audience deliberately. Feedback and a satisfying transformation matter more than an upgrade tree by itself.'),
3361470:('Short, enjoyable progression and music are praised; a positive review also questions late prestige pacing.','Complaints cover weak payoff/ending, repeated prestiges, too many transition/results screens, clicking burden and menu usability.','Avoid letting UI animation interrupt the repeated action. Test late-game progression and the ending, not just the first few upgrades.'),
4594150:('Players describe an enjoyable affordable loop and noticeable upgrades; some want additional content.','Complaints focus on grind, short/finite content relative to expectations, limited replay value and demo-to-full value. Allegations about abandonment or AI are reviewer claims, not verified facts.','Set a clear finite-content promise and make the demo/full distinction understandable. Do not add an endless mode solely because some reviewers request it.'),
2934520:('Old EA comments enjoy the skill tree and ascent choices; one asks for cloud saves.','The one qualifying negative comment objects to waiting and lack of depth.','Three positive comments are from EA, while the negative is post-1.0. This tiny, mixed-stage sample cannot explain commercial failure causally.')}
parts=['# Player review findings','','**Sample taken 21 October 2026: 99 reviews across 12 focal games.** [Return to market findings](market-findings.md).','','## Sampling method and limits','','For each game, request the five newest-created positive and five newest-created negative reviews through Steam’s public review endpoint: `filter=recent`, `language=english`, `purchase_type=steam`, `review_type=positive/negative`, `filter_offtopic_activity=1`, `num_per_page=5`. Keep fewer if unavailable; do not replace jokes, generic praise or off-topic comments with more convenient evidence. English is the stored language field, not a guarantee that every sentence is English. No 30-day cutoff was applied.','','Focal games cover close matches, different reception levels and release routes. This is a deliberately balanced diagnostic sample, not a random player sample and not an estimate of how common any opinion is. Five negatives from an overwhelmingly positive game do not imply half its buyers are unhappy. Comments can be edited after posting; links below identify the sampled reviews, while their created/updated timestamps are retained in the [fixed source index](research/review-sample-2026-10-21.json). Full review text and reviewer profile records were not copied into the repository.','','Themes below are manual paraphrases of substantive comments, including reservations within positive recommendations. Conflicting opinions are retained. Reported bugs and completion times were not independently reproduced. No causal claim is made that a cited complaint caused poor sales.','','## Sample coverage','','| Game | Positive / negative | Created-date span |','| --- | --- | --- |']
for a in themes:
    ss=[s for s in data if s['appid']==a]
    pos=next(s for s in ss if s['polarity']=='positive')['reviews']
    neg=next(s for s in ss if s['polarity']=='negative')['reviews']
    timestamps=[r['timestamp_created'] for r in pos+neg]
    fmt=lambda t:dt.datetime.fromtimestamp(t,dt.timezone.utc).date().isoformat()
    parts.append(f"| {rows[a]['name']} | {len(pos)} / {len(neg)} | {fmt(min(timestamps))} – {fmt(max(timestamps))} |")
parts+=['','No pooled rating is calculated from this sample. The all-language reception metrics are separately reported in the [market tables](market-comparison.md).','','## Observations and project implications','']
for a,(positive,negative,implication) in themes.items():
    parts += [f"### {rows[a]['name']}",'',f'**What appealed:** {positive}','',f'**Friction or objections:** {negative}','',f'**Our inference:** {implication}','']
    for polarity in ['positive','negative']:
        sample=next(s for s in data if s['appid']==a and s['polarity']==polarity)
        links=[f"[{i+1}]({r['url']})" for i,r in enumerate(sample['reviews'])]
        parts.append(f"Sampled {polarity} sources: "+(', '.join(links) if links else 'none available')+'.')
    parts+=['']
parts+=['## What to carry into production costing','','- Horror: connected camera/movement/combat tests, purposeful rooms, readable encounters, sound and story payoff. Low-poly art does not remove these tasks.','- Mech: targeting, weapon feedback, early access to meaningful build choices, distinct enemy roles and encounter variation. Include garage usability and compatibility tests.','- Incremental: action feedback, progression pacing, skippable/reduced interface interruption, automation that changes play and a satisfying finite ending.','','These priorities refine the asset and quality inventory; they do not authorize extra features or establish total development hours.','']
output.write_text('\n'.join(parts),encoding='utf-8')
print('Wrote review report; sample size:',sum(len(s['reviews']) for s in data))
